import{c as e,S as d,j as l,m as o}from"./chunks/framework.DBSVVeOL.js";const f=JSON.parse('{"title":"Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference.md","filePath":"reference.md","lastUpdated":null}'),c={name:"reference.md"};function n(a,t,s,r,i,y){return d(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="Reference" tabindex="-1">Reference <a class="header-anchor" href="#Reference" aria-label="Permalink to &quot;Reference {#Reference}&quot;">​</a></h1><p>This page summarizes the exported API. Guide pages show recommended usage; this page is for signatures, return types, and option names.</p><p>Conventions:</p><ul><li><p>Timeouts and durations are seconds.</p></li><li><p>Status enums are namespaced, for example <code>ConnectionStatus.CONNECTED</code> and <code>AckPolicy.EXPLICIT</code>.</p></li><li><p>Payload inputs may be strings, byte vectors, or <code>nothing</code>; encode structured values explicitly.</p></li><li><p><code>String(msg)</code> works for <code>Msg</code>, <code>JetStreamMsg</code>, and <code>KeyValueEntry</code>.</p></li><li><p>Blocking operations accept <code>cancel_token=cancellation_token(source)</code> where cancellation is useful.</p></li><li><p>Most <code>_async</code> helpers return <code>NatterTask</code>; <code>js_publish_async</code> returns <code>JetStreamPublishFuture</code>. <code>fetch(handle)</code> returns the operation result or rethrows the original error.</p></li></ul><h2 id="Core-Types" tabindex="-1">Core Types <a class="header-anchor" href="#Core-Types" aria-label="Permalink to &quot;Core Types {#Core-Types}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Type</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Client</code></td><td style="text-align:left;">Active connection with reader, ping, reconnect, request, and subscription state.</td></tr><tr><td style="text-align:left;"><code>ConnectOptions</code></td><td style="text-align:left;">Immutable connection configuration built by <code>connect</code> or directly.</td></tr><tr><td style="text-align:left;"><code>ConnectionStatus</code></td><td style="text-align:left;"><code>DISCONNECTED</code>, <code>CONNECTING</code>, <code>CONNECTED</code>, <code>RECONNECTING</code>, <code>DRAINING</code>, <code>CLOSED</code>.</td></tr><tr><td style="text-align:left;"><code>ConnectionEventKind</code></td><td style="text-align:left;">Lifecycle event kind for <code>event_cb</code>.</td></tr><tr><td style="text-align:left;"><code>ConnectionEvent</code></td><td style="text-align:left;">Event passed to <code>event_cb</code>; includes kind, status, URL, attempt, delay, error, and generation.</td></tr><tr><td style="text-align:left;"><code>Stats</code></td><td style="text-align:left;">Snapshot of message, byte, reconnect, error, and dropped-message counters.</td></tr><tr><td style="text-align:left;"><code>Msg</code></td><td style="text-align:left;">Core message with <code>subject</code>, <code>reply</code>, byte-vector <code>data</code>, and optional headers.</td></tr><tr><td style="text-align:left;"><code>Headers</code></td><td style="text-align:left;">Case-insensitive header dictionary of <code>String =&gt; Vector{String}</code>.</td></tr><tr><td style="text-align:left;"><code>PublishFrame</code></td><td style="text-align:left;">Prepared core publish frame from <code>prepare_publish</code>.</td></tr><tr><td style="text-align:left;"><code>Subscription</code></td><td style="text-align:left;">Core subscription handle.</td></tr><tr><td style="text-align:left;"><code>NatterTask</code></td><td style="text-align:left;">Explicit task handle returned by task-backed <code>_async</code> helpers.</td></tr><tr><td style="text-align:left;"><code>CancellationSource</code>, <code>CancellationToken</code></td><td style="text-align:left;">Cooperative cancellation source and token for blocking operations.</td></tr></tbody></table><h2 id="Authentication-Types" tabindex="-1">Authentication Types <a class="header-anchor" href="#Authentication-Types" aria-label="Permalink to &quot;Authentication Types {#Authentication-Types}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Type</th><th style="text-align:left;">Use</th></tr></thead><tbody><tr><td style="text-align:left;"><code>NoAuth()</code></td><td style="text-align:left;">No NATS authentication.</td></tr><tr><td style="text-align:left;"><code>TokenAuth(token)</code></td><td style="text-align:left;">Token auth.</td></tr><tr><td style="text-align:left;"><code>UserPassAuth(user, password)</code></td><td style="text-align:left;">Username/password auth.</td></tr><tr><td style="text-align:left;"><code>NKeyAuth(; seed=...)</code>, <code>NKeyAuth(; seed_path=...)</code></td><td style="text-align:left;">NKEY auth with local seed signing.</td></tr><tr><td style="text-align:left;"><code>NKeyAuth(; nkey=..., signature_cb=...)</code></td><td style="text-align:left;">NKEY auth with external signing.</td></tr><tr><td style="text-align:left;"><code>JwtAuth(; jwt=..., seed=...)</code>, <code>JwtAuth(; jwt_path=..., seed_path=...)</code></td><td style="text-align:left;">User JWT auth.</td></tr><tr><td style="text-align:left;"><code>CredentialsAuth(; path=...)</code>, <code>CredentialsAuth(credentials)</code></td><td style="text-align:left;">Standard decorated <code>.creds</code> auth.</td></tr><tr><td style="text-align:left;"><code>CallbackAuth(f)</code></td><td style="text-align:left;">Select auth after server <code>INFO</code>; <code>f(::AuthRequest)</code> returns a concrete auth value.</td></tr><tr><td style="text-align:left;"><code>AuthRequest</code></td><td style="text-align:left;">Callback context with server, URL, nonce, server info, attempt, and reconnect flag.</td></tr></tbody></table><h2 id="Connect-Options" tabindex="-1">Connect Options <a class="header-anchor" href="#Connect-Options" aria-label="Permalink to &quot;Connect Options {#Connect-Options}&quot;">​</a></h2><p><code>connect(url_or_urls=nothing; kwargs...)</code> accepts one URL, a vector/tuple of URLs, or no URL for <code>nats://localhost:4222</code>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Option</th><th style="text-align:left;">Default</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>name</code></td><td style="text-align:left;"><code>nothing</code></td><td style="text-align:left;">Human-readable connection name.</td></tr><tr><td style="text-align:left;"><code>auth</code></td><td style="text-align:left;"><code>NoAuth()</code></td><td style="text-align:left;">One typed authentication value.</td></tr><tr><td style="text-align:left;"><code>no_echo</code></td><td style="text-align:left;"><code>false</code></td><td style="text-align:left;">Do not receive this connection&#39;s own publishes.</td></tr><tr><td style="text-align:left;"><code>connect_timeout</code></td><td style="text-align:left;"><code>2.0</code></td><td style="text-align:left;">Socket and handshake timeout.</td></tr><tr><td style="text-align:left;"><code>ping_interval</code></td><td style="text-align:left;"><code>120.0</code></td><td style="text-align:left;">Keepalive interval.</td></tr><tr><td style="text-align:left;"><code>max_outstanding_pings</code></td><td style="text-align:left;"><code>2</code></td><td style="text-align:left;">Missed keepalives before reconnect.</td></tr><tr><td style="text-align:left;"><code>allow_reconnect</code></td><td style="text-align:left;"><code>true</code></td><td style="text-align:left;">Enable automatic reconnect.</td></tr><tr><td style="text-align:left;"><code>reconnect_wait</code></td><td style="text-align:left;"><code>0.5</code></td><td style="text-align:left;">Initial reconnect wait.</td></tr><tr><td style="text-align:left;"><code>reconnect_max_wait</code></td><td style="text-align:left;"><code>5.0</code></td><td style="text-align:left;">Maximum reconnect wait.</td></tr><tr><td style="text-align:left;"><code>reconnect_jitter</code></td><td style="text-align:left;"><code>0.1</code></td><td style="text-align:left;">Added reconnect jitter.</td></tr><tr><td style="text-align:left;"><code>max_reconnect_attempts</code></td><td style="text-align:left;"><code>-1</code></td><td style="text-align:left;"><code>-1</code> means unlimited attempts.</td></tr><tr><td style="text-align:left;"><code>pending_size</code></td><td style="text-align:left;"><code>2 MiB</code></td><td style="text-align:left;">Buffered publish bytes retained for reconnect replay.</td></tr><tr><td style="text-align:left;"><code>write_buffer_size</code></td><td style="text-align:left;"><code>32 KiB</code></td><td style="text-align:left;">Buffered write threshold; <code>0</code> disables buffering.</td></tr><tr><td style="text-align:left;"><code>write_buffer_latency</code></td><td style="text-align:left;"><code>0.001</code></td><td style="text-align:left;">Maximum small-write coalescing delay.</td></tr><tr><td style="text-align:left;"><code>write_timeout</code></td><td style="text-align:left;"><code>10.0</code></td><td style="text-align:left;">Maximum write/flush block time.</td></tr><tr><td style="text-align:left;"><code>record_stats</code></td><td style="text-align:left;"><code>false</code></td><td style="text-align:left;">Enable client counters returned by <code>stats(client)</code>.</td></tr><tr><td style="text-align:left;"><code>sub_pending_msgs_limit</code></td><td style="text-align:left;"><code>1024</code></td><td style="text-align:left;">Default per-subscription queued message limit.</td></tr><tr><td style="text-align:left;"><code>sub_pending_bytes_limit</code></td><td style="text-align:left;"><code>128 MiB</code></td><td style="text-align:left;">Default per-subscription queued byte limit.</td></tr><tr><td style="text-align:left;"><code>drain_timeout</code></td><td style="text-align:left;"><code>30.0</code></td><td style="text-align:left;">Default <code>drain</code> timeout.</td></tr><tr><td style="text-align:left;"><code>close_callback_timeout</code></td><td style="text-align:left;"><code>5.0</code></td><td style="text-align:left;">Wait for active callbacks during close.</td></tr><tr><td style="text-align:left;"><code>inbox_prefix</code></td><td style="text-align:left;"><code>&quot;_INBOX&quot;</code></td><td style="text-align:left;">Prefix for generated inbox subjects.</td></tr><tr><td style="text-align:left;"><code>error_cb</code></td><td style="text-align:left;">warning callback</td><td style="text-align:left;">Receives background, callback, and cleanup errors.</td></tr><tr><td style="text-align:left;"><code>event_cb</code></td><td style="text-align:left;">no-op</td><td style="text-align:left;">Receives <code>ConnectionEvent</code> lifecycle events.</td></tr><tr><td style="text-align:left;"><code>reconnect_delay_cb</code></td><td style="text-align:left;">no-op</td><td style="text-align:left;">Optional reconnect delay override.</td></tr></tbody></table><p>TLS options:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Option</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>tls_required</code></td><td style="text-align:left;">Require TLS even for <code>nats://</code> URLs.</td></tr><tr><td style="text-align:left;"><code>tls_first</code></td><td style="text-align:left;">Force TLS-first or INFO-first behavior.</td></tr><tr><td style="text-align:left;"><code>tls_verify</code></td><td style="text-align:left;">Verify server certificates; default <code>true</code>.</td></tr><tr><td style="text-align:left;"><code>tls_server_name</code></td><td style="text-align:left;">Override SNI and certificate name verification.</td></tr><tr><td style="text-align:left;"><code>tls_ca_path</code></td><td style="text-align:left;">CA bundle/path.</td></tr><tr><td style="text-align:left;"><code>tls_cert_path</code>, <code>tls_key_path</code></td><td style="text-align:left;">Client certificate and key for mTLS.</td></tr></tbody></table><p>Parser/resource limits:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Option</th><th style="text-align:left;">Default</th></tr></thead><tbody><tr><td style="text-align:left;"><code>max_control_line</code></td><td style="text-align:left;"><code>16 KiB</code></td></tr><tr><td style="text-align:left;"><code>max_inbound_payload</code></td><td style="text-align:left;"><code>64 MiB</code></td></tr><tr><td style="text-align:left;"><code>max_header_bytes</code></td><td style="text-align:left;"><code>64 KiB</code></td></tr><tr><td style="text-align:left;"><code>max_stale_pong_waiters</code></td><td style="text-align:left;"><code>1024</code></td></tr></tbody></table><h2 id="Core-Functions" tabindex="-1">Core Functions <a class="header-anchor" href="#Core-Functions" aria-label="Permalink to &quot;Core Functions {#Core-Functions}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function</th><th style="text-align:left;">Returns</th><th style="text-align:left;">Use</th></tr></thead><tbody><tr><td style="text-align:left;"><code>connect(url_or_urls=nothing; kwargs...)</code></td><td style="text-align:left;"><code>Client</code></td><td style="text-align:left;">Connect to NATS.</td></tr><tr><td style="text-align:left;"><code>publish(client, subject, data=nothing; reply=nothing, headers=nothing)</code></td><td style="text-align:left;"><code>nothing</code></td><td style="text-align:left;">Publish a core message. Payloads are <code>nothing</code>, strings, or byte vectors.</td></tr><tr><td style="text-align:left;"><code>prepare_publish(subject, data=nothing; reply=nothing, headers=nothing)</code></td><td style="text-align:left;"><code>PublishFrame</code></td><td style="text-align:left;">Validate and serialize a reusable publish frame. Payloads are <code>nothing</code>, strings, or byte vectors.</td></tr><tr><td style="text-align:left;"><code>publish(client, frame::PublishFrame)</code></td><td style="text-align:left;"><code>nothing</code></td><td style="text-align:left;">Publish a prepared frame.</td></tr><tr><td style="text-align:left;"><code>subscribe(client, subject; queue=nothing, callback=nothing, max_msgs=0, pending_msgs_limit=..., pending_bytes_limit=...)</code></td><td style="text-align:left;"><code>Subscription</code></td><td style="text-align:left;">Create a subscription.</td></tr><tr><td style="text-align:left;"><code>subscribe(callback, client, subject; kwargs...)</code></td><td style="text-align:left;"><code>Subscription</code></td><td style="text-align:left;">Callback-first form.</td></tr><tr><td style="text-align:left;"><code>next(sub; timeout=1.0)</code></td><td style="text-align:left;"><code>Msg</code></td><td style="text-align:left;">Wait for a message on a non-callback subscription.</td></tr><tr><td style="text-align:left;"><code>unsubscribe(sub; max_msgs=0)</code></td><td style="text-align:left;"><code>nothing</code></td><td style="text-align:left;">Unsubscribe now or after more messages.</td></tr><tr><td style="text-align:left;"><code>close(sub)</code></td><td style="text-align:left;"><code>nothing</code></td><td style="text-align:left;">Alias for immediate unsubscribe.</td></tr><tr><td style="text-align:left;"><code>request(client, subject, data=nothing; timeout=1.0, headers=nothing)</code></td><td style="text-align:left;"><code>Msg</code></td><td style="text-align:left;">Send a request and wait for one reply. Payloads are <code>nothing</code>, strings, or byte vectors.</td></tr><tr><td style="text-align:left;"><code>flush(client; timeout=10.0)</code></td><td style="text-align:left;"><code>nothing</code></td><td style="text-align:left;">Wait for a server round trip.</td></tr><tr><td style="text-align:left;"><code>ping(client; timeout=10.0)</code></td><td style="text-align:left;"><code>nothing</code></td><td style="text-align:left;">Alias for <code>flush</code>.</td></tr><tr><td style="text-align:left;"><code>drain(sub; timeout=...)</code></td><td style="text-align:left;"><code>nothing</code></td><td style="text-align:left;">Unsubscribe and wait for queued callback work.</td></tr><tr><td style="text-align:left;"><code>drain(client; timeout=...)</code></td><td style="text-align:left;"><code>nothing</code></td><td style="text-align:left;">Drain subscriptions, flush, and close.</td></tr><tr><td style="text-align:left;"><code>close(client; throw_errors=false, callback_timeout=nothing)</code></td><td style="text-align:left;"><code>nothing</code></td><td style="text-align:left;">Close the client.</td></tr><tr><td style="text-align:left;"><code>new_inbox(client; prefix=...)</code></td><td style="text-align:left;"><code>String</code></td><td style="text-align:left;">Generate an inbox subject.</td></tr><tr><td style="text-align:left;"><code>header(msg, key)</code></td><td style="text-align:left;"><code>Union{String,Nothing}</code></td><td style="text-align:left;">First header value by case-insensitive key.</td></tr><tr><td style="text-align:left;"><code>headers(msg)</code></td><td style="text-align:left;"><code>Headers</code></td><td style="text-align:left;">Copy all message headers.</td></tr><tr><td style="text-align:left;"><code>status(client)</code></td><td style="text-align:left;"><code>ConnectionStatus.T</code></td><td style="text-align:left;">Current connection status.</td></tr><tr><td style="text-align:left;"><code>stats(client)</code></td><td style="text-align:left;"><code>Stats</code></td><td style="text-align:left;">Counter snapshot; byte counters include payload and header bytes.</td></tr><tr><td style="text-align:left;"><code>connected_url(client)</code></td><td style="text-align:left;"><code>Union{String,Nothing}</code></td><td style="text-align:left;">Current server URL.</td></tr></tbody></table><p>Core async helpers: <code>connect_async</code>, <code>publish_async</code>, <code>subscribe_async</code>, <code>unsubscribe_async</code>, <code>next_async</code>, <code>request_async</code>, <code>flush_async</code>, <code>ping_async</code>, <code>drain_async</code>, and <code>close_async</code>.</p><p>Cancellation helpers: <code>CancellationSource()</code>, <code>cancellation_token(source)</code>, <code>cancel!(source)</code>, and <code>iscancelled(token)</code>. Cancelled operations throw <code>CancelledError</code>; <code>_async</code> helpers rethrow the same error from <code>fetch(handle)</code>.</p><h2 id="JetStream-Types" tabindex="-1">JetStream Types <a class="header-anchor" href="#JetStream-Types" aria-label="Permalink to &quot;JetStream Types {#JetStream-Types}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Type</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>JetStreamContext</code></td><td style="text-align:left;">JetStream API context from <code>jetstream(client)</code>.</td></tr><tr><td style="text-align:left;"><code>StreamConfig</code></td><td style="text-align:left;">Typed stream configuration.</td></tr><tr><td style="text-align:left;"><code>ConsumerConfig</code></td><td style="text-align:left;">Typed consumer configuration.</td></tr><tr><td style="text-align:left;"><code>StreamInfo</code>, <code>StreamState</code>, <code>StreamLostData</code></td><td style="text-align:left;">Typed stream info responses.</td></tr><tr><td style="text-align:left;"><code>ConsumerInfo</code>, <code>ConsumerSequenceInfo</code></td><td style="text-align:left;">Typed consumer info responses.</td></tr><tr><td style="text-align:left;"><code>PubAck</code></td><td style="text-align:left;">Publish acknowledgement.</td></tr><tr><td style="text-align:left;"><code>JetStreamPublishFuture</code></td><td style="text-align:left;">Future returned by protocol-level async JetStream publish.</td></tr><tr><td style="text-align:left;"><code>JetStreamMsg</code></td><td style="text-align:left;">Consumer message with acknowledgement state.</td></tr><tr><td style="text-align:left;"><code>PullSubscription</code>, <code>PullMessageStream</code>, <code>PushSubscription</code></td><td style="text-align:left;">Consumer handles.</td></tr></tbody></table><p>Enums:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Namespace</th><th style="text-align:left;">Values</th></tr></thead><tbody><tr><td style="text-align:left;"><code>RetentionPolicy</code></td><td style="text-align:left;"><code>LIMITS</code>, <code>INTEREST</code>, <code>WORK_QUEUE</code></td></tr><tr><td style="text-align:left;"><code>StorageType</code></td><td style="text-align:left;"><code>FILE</code>, <code>MEMORY</code></td></tr><tr><td style="text-align:left;"><code>DiscardPolicy</code></td><td style="text-align:left;"><code>OLD</code>, <code>NEW</code></td></tr><tr><td style="text-align:left;"><code>StoreCompression</code></td><td style="text-align:left;"><code>NONE</code>, <code>S2</code></td></tr><tr><td style="text-align:left;"><code>PersistMode</code></td><td style="text-align:left;"><code>DEFAULT</code>, <code>ASYNC</code></td></tr><tr><td style="text-align:left;"><code>AckPolicy</code></td><td style="text-align:left;"><code>NONE</code>, <code>ALL</code>, <code>EXPLICIT</code></td></tr><tr><td style="text-align:left;"><code>DeliverPolicy</code></td><td style="text-align:left;"><code>ALL</code>, <code>LAST</code>, <code>NEW</code>, <code>BY_START_SEQUENCE</code>, <code>BY_START_TIME</code>, <code>LAST_PER_SUBJECT</code></td></tr><tr><td style="text-align:left;"><code>ReplayPolicy</code></td><td style="text-align:left;"><code>INSTANT</code>, <code>ORIGINAL</code></td></tr><tr><td style="text-align:left;"><code>PriorityPolicy</code></td><td style="text-align:left;"><code>NONE</code>, <code>OVERFLOW</code>, <code>PINNED_CLIENT</code>, <code>PRIORITIZED</code></td></tr></tbody></table><p>Stream config helpers: <code>Placement</code>, <code>ExternalStreamSource</code>, <code>SubjectTransform</code>, <code>StreamSource</code>, <code>StreamConsumerLimits</code>, and <code>RePublish</code>.</p><h2 id="JetStream-Functions" tabindex="-1">JetStream Functions <a class="header-anchor" href="#JetStream-Functions" aria-label="Permalink to &quot;JetStream Functions {#JetStream-Functions}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function</th><th style="text-align:left;">Returns</th><th style="text-align:left;">Use</th></tr></thead><tbody><tr><td style="text-align:left;"><code>jetstream(client; prefix=&quot;$JS.API&quot;, timeout=5.0, publish_async_max_pending=256)</code></td><td style="text-align:left;"><code>JetStreamContext</code></td><td style="text-align:left;">Create a context.</td></tr><tr><td style="text-align:left;"><code>js_publish(js, subject, data=nothing; kwargs...)</code></td><td style="text-align:left;"><code>PubAck</code></td><td style="text-align:left;">Publish and wait for an ack.</td></tr><tr><td style="text-align:left;"><code>js_publish_async(js, subject, data=nothing; kwargs...)</code></td><td style="text-align:left;"><code>JetStreamPublishFuture</code></td><td style="text-align:left;">Publish with the context async publisher and return an ack future. Pending futures are failed, not replayed, on reconnect.</td></tr><tr><td style="text-align:left;"><code>fetch(future::JetStreamPublishFuture)</code></td><td style="text-align:left;"><code>PubAck</code></td><td style="text-align:left;">Wait for the async publish ack or rethrow its error.</td></tr><tr><td style="text-align:left;"><code>js_publish_async_pending(js)</code></td><td style="text-align:left;"><code>Int</code></td><td style="text-align:left;">Count async publishes still waiting for acks.</td></tr><tr><td style="text-align:left;"><code>js_publish_async_complete(js; timeout=...)</code></td><td style="text-align:left;"><code>nothing</code></td><td style="text-align:left;">Wait until all pending async publishes on the context complete.</td></tr><tr><td style="text-align:left;"><code>stream_create(js, config; timeout=...)</code></td><td style="text-align:left;"><code>StreamInfo</code></td><td style="text-align:left;">Create a stream.</td></tr><tr><td style="text-align:left;"><code>stream_update(js, config; timeout=...)</code></td><td style="text-align:left;"><code>StreamInfo</code></td><td style="text-align:left;">Update a stream.</td></tr><tr><td style="text-align:left;"><code>stream_info(js, name; timeout=...)</code></td><td style="text-align:left;"><code>StreamInfo</code></td><td style="text-align:left;">Fetch stream info.</td></tr><tr><td style="text-align:left;"><code>stream_list(js; offset=0, timeout=...)</code></td><td style="text-align:left;"><code>Vector{StreamInfo}</code></td><td style="text-align:left;">List streams.</td></tr><tr><td style="text-align:left;"><code>stream_names(js; subject=nothing, timeout=...)</code></td><td style="text-align:left;"><code>Vector{String}</code></td><td style="text-align:left;">List stream names.</td></tr><tr><td style="text-align:left;"><code>stream_purge(js, name; filter_subject=nothing, keep=nothing, timeout=...)</code></td><td style="text-align:left;"><code>Bool</code></td><td style="text-align:left;">Purge a stream or subject subset.</td></tr><tr><td style="text-align:left;"><code>stream_delete(js, name; timeout=...)</code></td><td style="text-align:left;"><code>Bool</code></td><td style="text-align:left;">Delete a stream.</td></tr><tr><td style="text-align:left;"><code>stream_message_get(js, stream; seq=nothing, subject=nothing, direct=false, next_by_subject=false, timeout=...)</code></td><td style="text-align:left;"><code>Msg</code></td><td style="text-align:left;">Read a stored message.</td></tr><tr><td style="text-align:left;"><code>stream_message_delete(js, stream, seq; timeout=...)</code></td><td style="text-align:left;"><code>Bool</code></td><td style="text-align:left;">Delete one stored message.</td></tr><tr><td style="text-align:left;"><code>consumer_create(js, stream, config; timeout=...)</code></td><td style="text-align:left;"><code>ConsumerInfo</code></td><td style="text-align:left;">Strict create.</td></tr><tr><td style="text-align:left;"><code>consumer_create_or_update(js, stream, config; timeout=...)</code></td><td style="text-align:left;"><code>ConsumerInfo</code></td><td style="text-align:left;">Explicit upsert.</td></tr><tr><td style="text-align:left;"><code>consumer_update(js, stream, config; timeout=...)</code></td><td style="text-align:left;"><code>ConsumerInfo</code></td><td style="text-align:left;">Strict update.</td></tr><tr><td style="text-align:left;"><code>consumer_info(js, stream, consumer; timeout=...)</code></td><td style="text-align:left;"><code>ConsumerInfo</code></td><td style="text-align:left;">Fetch consumer info.</td></tr><tr><td style="text-align:left;"><code>consumer_list(js, stream; offset=0, timeout=...)</code></td><td style="text-align:left;"><code>Vector{ConsumerInfo}</code></td><td style="text-align:left;">List consumers.</td></tr><tr><td style="text-align:left;"><code>consumer_delete(js, stream, consumer; timeout=...)</code></td><td style="text-align:left;"><code>Bool</code></td><td style="text-align:left;">Delete a consumer.</td></tr><tr><td style="text-align:left;"><code>pull_subscribe(js, subject; stream=nothing, durable=nothing, config=ConsumerConfig(), timeout=...)</code></td><td style="text-align:left;"><code>PullSubscription</code></td><td style="text-align:left;">Create or bind a pull consumer.</td></tr><tr><td style="text-align:left;"><code>fetch(psub, batch=1; timeout=..., expires=..., heartbeat=nothing, max_bytes=nothing, no_wait=false, min_pending=nothing, min_ack_pending=nothing, priority_group=nothing, priority=nothing, cancel_token=nothing)</code></td><td style="text-align:left;"><code>Vector{JetStreamMsg}</code></td><td style="text-align:left;">Fetch a bounded batch.</td></tr><tr><td style="text-align:left;"><code>messages(psub; batch=100, max_bytes=nothing, expires=30.0, heartbeat=nothing, threshold_messages=nothing, threshold_bytes=nothing, channel_size=batch, stop_after=nothing, min_pending=nothing, min_ack_pending=nothing, priority_group=nothing, priority=nothing)</code></td><td style="text-align:left;"><code>PullMessageStream</code></td><td style="text-align:left;">Start a bounded refill stream.</td></tr><tr><td style="text-align:left;"><code>consume(callback, psub; kwargs...)</code></td><td style="text-align:left;"><code>PullMessageStream</code></td><td style="text-align:left;">Run a callback over <code>messages</code>.</td></tr><tr><td style="text-align:left;"><code>push_subscribe(js, subject; stream=nothing, durable=nothing, queue=nothing, callback=nothing, manual_ack=false, config=ConsumerConfig(), timeout=..., ordered=false)</code></td><td style="text-align:left;"><code>PushSubscription</code></td><td style="text-align:left;">Create or bind a push consumer, or create an ordered ephemeral push consumer with <code>ordered=true</code>.</td></tr><tr><td style="text-align:left;"><code>next(psub::PushSubscription; timeout=1.0)</code></td><td style="text-align:left;"><code>JetStreamMsg</code></td><td style="text-align:left;">Read from a channel-backed push subscription.</td></tr><tr><td style="text-align:left;"><code>ack(msg)</code>, <code>ack_sync(msg; timeout=1.0)</code>, <code>nak(msg; delay=nothing)</code>, <code>in_progress(msg)</code>, <code>term(msg)</code></td><td style="text-align:left;"><code>nothing</code> or <code>Msg</code></td><td style="text-align:left;">Acknowledge or control redelivery.</td></tr><tr><td style="text-align:left;"><code>metadata(msg)</code></td><td style="text-align:left;"><code>MsgMetadata</code></td><td style="text-align:left;">Parse JetStream delivery metadata.</td></tr><tr><td style="text-align:left;"><code>close(psub)</code>, <code>close(push)</code>, <code>close(stream)</code></td><td style="text-align:left;"><code>nothing</code></td><td style="text-align:left;">Close consumer/message handles.</td></tr></tbody></table><p>Typed <code>StreamConfig</code> and <code>ConsumerConfig</code> create/update calls verify that requested fields are reflected in the server response, including explicit false, zero, and empty values. Raw dictionary configs are pass-through for fields outside Natter&#39;s typed API.</p><p>JetStream task-backed async helpers mirror management, subscribe, fetch, close, and acknowledgement functions: <code>stream_*_async</code>, <code>consumer_*_async</code>, <code>pull_subscribe_async</code>, <code>push_subscribe_async</code>, <code>fetch_async</code>, <code>ack_async</code>, <code>ack_sync_async</code>, <code>nak_async</code>, <code>in_progress_async</code>, <code>term_async</code>, and <code>js_publish_async_complete_async</code>. <code>js_publish_async</code> is different: it is the protocol async publisher and returns <code>JetStreamPublishFuture</code>.</p><h2 id="KeyValue-Types" tabindex="-1">KeyValue Types <a class="header-anchor" href="#KeyValue-Types" aria-label="Permalink to &quot;KeyValue Types {#KeyValue-Types}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Type</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>KeyValue</code></td><td style="text-align:left;">Bucket handle.</td></tr><tr><td style="text-align:left;"><code>KeyValueEntry</code></td><td style="text-align:left;">Bucket entry with <code>bucket</code>, <code>key</code>, <code>value</code>, <code>revision</code>, <code>created</code>, <code>delta</code>, and <code>operation</code>.</td></tr><tr><td style="text-align:left;"><code>KeyValueOperation</code></td><td style="text-align:left;"><code>PUT</code>, <code>DELETE</code>, <code>PURGE</code>.</td></tr><tr><td style="text-align:left;"><code>KeyValueStatus</code></td><td style="text-align:left;">Bucket status and backing stream info.</td></tr><tr><td style="text-align:left;"><code>KeyValueWatcher</code></td><td style="text-align:left;">Watch handle with <code>updates</code> channel and <code>take!(watcher)</code>.</td></tr><tr><td style="text-align:left;"><code>KV_WATCH_INITIAL_DONE</code></td><td style="text-align:left;">Sentinel emitted by channel watchers after the initial snapshot.</td></tr></tbody></table><h2 id="KeyValue-Functions" tabindex="-1">KeyValue Functions <a class="header-anchor" href="#KeyValue-Functions" aria-label="Permalink to &quot;KeyValue Functions {#KeyValue-Functions}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function</th><th style="text-align:left;">Returns</th><th style="text-align:left;">Use</th></tr></thead><tbody><tr><td style="text-align:left;"><code>kv_create(js, bucket; history=1, ttl=nothing, max_bytes=-1, max_value_size=-1, storage=&quot;file&quot;, replicas=1, direct=false, compression=nothing, metadata=nothing, limit_marker_ttl=nothing, timeout=...)</code></td><td style="text-align:left;"><code>KeyValue</code></td><td style="text-align:left;">Create a bucket.</td></tr><tr><td style="text-align:left;"><code>kv_open(js, bucket; timeout=...)</code></td><td style="text-align:left;"><code>KeyValue</code></td><td style="text-align:left;">Open an existing bucket.</td></tr><tr><td style="text-align:left;"><code>kv_delete_bucket(kv; timeout=...)</code></td><td style="text-align:left;"><code>Bool</code></td><td style="text-align:left;">Delete the bucket.</td></tr><tr><td style="text-align:left;"><code>kv_status(kv; timeout=...)</code></td><td style="text-align:left;"><code>KeyValueStatus</code></td><td style="text-align:left;">Inspect bucket state.</td></tr><tr><td style="text-align:left;"><code>kv_get(kv, key; revision=nothing, direct=nothing, timeout=...)</code></td><td style="text-align:left;"><code>KeyValueEntry</code></td><td style="text-align:left;">Read a key.</td></tr><tr><td style="text-align:left;"><code>kv_put(kv, key, value; revision=nothing, ttl=nothing, timeout=...)</code></td><td style="text-align:left;"><code>Int</code></td><td style="text-align:left;">Put a value and return the new revision.</td></tr><tr><td style="text-align:left;"><code>kv_create_key(kv, key, value; ttl=nothing, timeout=...)</code></td><td style="text-align:left;"><code>Int</code></td><td style="text-align:left;">Put only if absent or deleted.</td></tr><tr><td style="text-align:left;"><code>kv_update(kv, key, value, revision; ttl=nothing, timeout=...)</code></td><td style="text-align:left;"><code>Int</code></td><td style="text-align:left;">Put only at the expected revision.</td></tr><tr><td style="text-align:left;"><code>kv_delete(kv, key; revision=nothing, timeout=...)</code></td><td style="text-align:left;"><code>nothing</code></td><td style="text-align:left;">Mark a key deleted.</td></tr><tr><td style="text-align:left;"><code>kv_purge(kv, key; revision=nothing, ttl=nothing, timeout=...)</code></td><td style="text-align:left;"><code>nothing</code></td><td style="text-align:left;">Purge prior values for a key.</td></tr><tr><td style="text-align:left;"><code>kv_purge_deletes(kv; older_than=1800.0, timeout=...)</code></td><td style="text-align:left;"><code>nothing</code></td><td style="text-align:left;">Remove old delete and purge markers.</td></tr><tr><td style="text-align:left;"><code>kv_history(kv, key; batch=256, timeout=...)</code></td><td style="text-align:left;"><code>Vector{KeyValueEntry}</code></td><td style="text-align:left;">Read key history.</td></tr><tr><td style="text-align:left;"><code>kv_keys(kv; timeout=...)</code></td><td style="text-align:left;"><code>Vector{String}</code></td><td style="text-align:left;">List active keys.</td></tr><tr><td style="text-align:left;"><code>kv_watch(kv; key=&quot;&gt;&quot;, keys=nothing, history=false, updates_only=false, ignore_deletes=false, meta_only=false, resume_revision=nothing, channel_size=256, notify_initial_done=false, timeout=...)</code></td><td style="text-align:left;"><code>KeyValueWatcher</code></td><td style="text-align:left;">Watch with a channel.</td></tr><tr><td style="text-align:left;"><code>kv_watch(callback, kv; kwargs...)</code></td><td style="text-align:left;"><code>KeyValueWatcher</code></td><td style="text-align:left;">Watch with a callback.</td></tr><tr><td style="text-align:left;"><code>close(watcher)</code></td><td style="text-align:left;"><code>nothing</code></td><td style="text-align:left;">Close a watcher.</td></tr></tbody></table><p>KeyValue async helpers: <code>kv_create_async</code>, <code>kv_open_async</code>, <code>kv_delete_bucket_async</code>, <code>kv_status_async</code>, <code>kv_get_async</code>, <code>kv_put_async</code>, <code>kv_create_key_async</code>, <code>kv_update_async</code>, <code>kv_delete_async</code>, <code>kv_purge_async</code>, <code>kv_purge_deletes_async</code>, <code>kv_history_async</code>, <code>kv_keys_async</code>, <code>kv_watch_async</code>, and <code>close_async(watcher)</code>.</p><h2 id="Errors" tabindex="-1">Errors <a class="header-anchor" href="#Errors" aria-label="Permalink to &quot;Errors {#Errors}&quot;">​</a></h2><p>All public error types derive from <code>NatterError</code>.</p><p>Core and connection errors: <code>TimeoutError</code>, <code>NoRespondersError</code>, <code>ConnectionClosedError</code>, <code>ConnectionReconnectingError</code>, <code>ConnectionDrainingError</code>, <code>ProtocolError</code>, <code>AuthenticationError</code>, <code>AuthorizationError</code>, <code>AuthenticationExpiredError</code>, <code>AuthenticationRevokedError</code>, <code>AccountAuthenticationExpiredError</code>, <code>PermissionViolationError</code>, <code>NoServersError</code>, <code>MaxPayloadError</code>, <code>OutboundBufferLimitError</code>, <code>SlowConsumerError</code>, <code>UnsupportedFeatureError</code>, and <code>CleanupError</code>.</p><p>JetStream errors: <code>JetStreamError</code>, <code>FetchDisconnectedError</code>, and <code>ConsumerSequenceMismatchError</code>.</p><p>KeyValue errors: <code>KeyValueError</code>, <code>KeyValueKeyNotFoundError</code>, <code>KeyValueKeyDeletedError</code>, <code>KeyValueWrongRevisionError</code>, and <code>KeyValueKeyExistsError</code>.</p>',38)])])}const u=e(c,[["render",n]]);export{f as __pageData,u as default};
